"""Port of SchedulerErrorHandlingTests.java.

Java rewrites the exception's stack trace to splice in the frames where the failing command
was bound/scheduled. Python keeps the real traceback and attaches the binding site as an
exception note (PEP 678) headed "=== Command Binding Trace ===".
"""

import pytest

from commands3._common.api import Canceled, Command, CompletedWithError, Mounted, Scheduled, Trigger, Yielded
from commands3._frontends.asyncgen import Coroutine, co

from .helpers import DummyMechanism


def _binding_note(exc) -> str:
    notes = [n for n in getattr(exc, "__notes__", []) if n.startswith("=== Command Binding Trace ===")]
    assert len(notes) == 1, getattr(exc, "__notes__", None)
    return notes[0]


def test_error_detection(scheduler):
    mechanism = DummyMechanism("X", scheduler)

    def bad():
        raise RuntimeError("The exception")

    command = mechanism.run(bad).named("Bad Behavior")
    Trigger(scheduler, lambda: True).on_true(command)
    with pytest.raises(RuntimeError) as e:
        scheduler.run()
    assert str(e.value) == "The exception"
    assert e.traceback[-1].name == "bad"
    note = _binding_note(e.value)
    assert "test_error_detection" in note, note


def test_nested_error_detection(scheduler):
    def c3():
        [][-1]

    async def c2():
        Trigger(scheduler, lambda: True).on_true(
            Command.no_requirements(c3).named("Throws IndexError"))
        await co.park()

    async def body():
        await co.await_(Command.no_requirements(c2).named("Schedules With Trigger"))

    scheduler.schedule(Command.no_requirements(body).named("Schedules Directly"))
    scheduler.run()
    with pytest.raises(IndexError) as e:
        scheduler.run()
    assert e.traceback[-1].name == "c3"
    note = _binding_note(e.value)
    assert "c2" in note and "test_nested_error_detection" not in note.split("c2")[0], note


def test_command_encountering_error_cancels_children(scheduler):
    child = Command.no_requirements(co.park).named("Child 1")

    def body():
        co.fork(child)
        raise RuntimeError("The exception")

    command = Command.no_requirements(body).named("Bad Behavior")
    scheduler.schedule(command)
    with pytest.raises(RuntimeError):
        scheduler.run()
    assert not scheduler.is_scheduled_or_running(command)
    assert not scheduler.is_scheduled_or_running(child)


def test_child_command_encountering_error_cancels_parent(scheduler):
    def child_body():
        raise RuntimeError("The exception")  # bubbles up to the parent

    child = Command.no_requirements(child_body).named("Child 1")

    async def body():
        await co.await_(child)
        await co.park()

    command = Command.no_requirements(body).named("Parent")
    scheduler.schedule(command)
    with pytest.raises(RuntimeError):
        scheduler.run()
    assert not scheduler.is_running(command)
    assert not scheduler.is_running(child)


def test_child_command_encountering_error_after_remount_cancels_parent(scheduler, events):
    async def child_body():
        yield
        raise RuntimeError("The exception")  # does not bubble up to the parent

    child = Command.no_requirements(child_body).named("Child 1")

    async def body():
        await co.await_(child)
        await co.park()

    command = Command.no_requirements(body).named("Parent")
    scheduler.schedule(command)
    scheduler.run()
    with pytest.raises(RuntimeError) as e:
        scheduler.run()
    error = e.value
    assert not scheduler.is_running(command)
    assert not scheduler.is_running(child)
    expected = [
        (Scheduled, command), (Mounted, command), (Scheduled, child), (Mounted, child),
        (Yielded, child), (Yielded, command), (Mounted, child), (CompletedWithError, child),
        (Canceled, command),
    ]
    assert [(type(ev), ev.command) for ev in events] == expected
    assert events[7].error is error
